const Board = ({ gameData, socket }) => {
  const gridSize = 11; // Board size
  const centerIndex = Math.floor(gridSize / 2); // Center index for cross shape

  const { pieces: initialPieces } = gameData.board;
  const { players } = gameData;

  const [pieces, setPieces] = useState(initialPieces); // Store positions of the pieces
  const [loading, setLoading] = useState(false); // Flag to track if a move is in progress
  const [error, setError] = useState(null); // Store error messages
  const [statusMessage, setStatusMessage] = useState(""); // Store status message
  const [diceRoll, setDiceRoll] = useState(null); // Store the dice roll result

  // Pre-calculate tile colors for each player
  const calculateTileColors = () => {
    const colorMap = new Map();

    players.forEach((player, index) => {
      let tiles = [];
      if (index === 0) {
        tiles = [
          [4, 0], [5, 1], [5, 2], [5, 3], [5, 4], [0, 0], [0, 1], [1, 0], [1, 1]
        ];
      } else if (index === 1) {
        tiles = [
          [0, 6], [1, 5], [2, 5], [3, 5], [4, 5], [0, 9], [0, 10], [1, 9], [1, 10]
        ];
      } else if (index === 2) {
        tiles = [
          [6, 10], [5, 6], [5, 7], [5, 8], [5, 9], [9, 9], [10, 9], [9, 10], [10, 10]
        ];
      } else if (index === 3) {
        tiles = [
          [10, 4], [6, 5], [7, 5], [8, 5], [9, 5], [9, 0], [9, 1], [10, 0], [10, 1]
        ];
      }

      tiles.forEach(([row, col]) => {
        colorMap.set(`${row}-${col}`, player.color);
      });
    });

    return colorMap;
  };

  const tileColorMap = calculateTileColors();

  const isCrossTile = (row, col) => {
    if (row === centerIndex && col === centerIndex) {
      return false;
    }

    return (
      (col >= centerIndex - 1 && col <= centerIndex + 1) ||
      (row >= centerIndex - 1 && row <= centerIndex + 1) ||
      (row <= 1 && col <= 1) ||
      (row >= 9 && col >= 9) ||
      (row <= 1 && col >= 9) ||
      (row >= 9 && col <= 1)
    );
  };

  const getTileColor = (row, col) => {
    if (!isCrossTile(row, col)) return 'white';
    return tileColorMap.get(`${row}-${col}`) || 'white';
  };

  const renderPiece = (row, col) => {
    const piece = pieces.find(p => {
      const { row: pieceRow, col: pieceCol } = getCoordinatesFromValue(p.position, p.color);
      return pieceRow === row && pieceCol === col;
    });

    if (piece) {
      return (
        <div
          className="piece"
          style={{ backgroundColor: piece.color, width: '70%', height: '70%' }}
        ></div>
      );
    }
    return null;
  };

  return (
    <div>
      <div className="board">
        {Array.from({ length: gridSize * gridSize }).map((_, index) => {
          const row = Math.floor(index / gridSize);
          const col = index % gridSize;
          const tileColor = getTileColor(row, col);

          return (
            <div
              className={`tile ${isCrossTile(row, col) ? '' : 'empty-tile'}`}
              style={{
                backgroundColor: tileColor,
                width: '40px',
                height: '40px',
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                border: '1px solid #ccc',
                cursor: 'pointer',
              }}
              key={index}
            >
              {renderPiece(row, col)}
            </div>
          );
        })}
      </div>
      {statusMessage && <div className="status-message">{statusMessage}</div>}
      {error && <div className="error">{error}</div>}
    </div>
  );
};

export default Board;
